const http = require("http")
const { parse: parseUrl } = require("url")

function normalizePath(pathValue) {
  if (!pathValue) {
    return "/"
  }

  if (!pathValue.startsWith("/")) {
    return `/${pathValue}`
  }

  return pathValue.replace(/\/+$/, "") || "/"
}

function joinPaths(parentPath, childPath) {
  const normalizedParent = normalizePath(parentPath)
  const normalizedChild = normalizePath(childPath)

  if (normalizedParent === "/") {
    return normalizedChild
  }

  if (normalizedChild === "/") {
    return normalizedParent
  }

  return `${normalizedParent}${normalizedChild}`.replace(/\/+/g, "/")
}

function splitPath(pathValue) {
  return normalizePath(pathValue).split("/").filter(Boolean)
}

function matchPath(pattern, actualPath) {
  const patternSegments = splitPath(pattern)
  const actualSegments = splitPath(actualPath)

  if (patternSegments.length !== actualSegments.length) {
    return null
  }

  const params = {}

  for (let index = 0; index < patternSegments.length; index += 1) {
    const patternSegment = patternSegments[index]
    const actualSegment = actualSegments[index]

    if (patternSegment.startsWith(":")) {
      params[patternSegment.slice(1)] = decodeURIComponent(actualSegment)
      continue
    }

    if (patternSegment !== actualSegment) {
      return null
    }
  }

  return params
}

function enhanceResponse(res) {
  res.status = function status(code) {
    res.statusCode = code
    return res
  }

  res.set = function set(headerName, value) {
    res.setHeader(headerName, value)
    return res
  }

  res.json = function json(payload) {
    if (!res.getHeader("Content-Type")) {
      res.setHeader("Content-Type", "application/json; charset=utf-8")
    }
    res.end(JSON.stringify(payload))
    return res
  }

  res.send = function send(payload) {
    if (Buffer.isBuffer(payload)) {
      res.end(payload)
      return res
    }

    if (typeof payload === "object" && payload !== null) {
      return res.json(payload)
    }

    if (!res.getHeader("Content-Type")) {
      res.setHeader("Content-Type", "text/plain; charset=utf-8")
    }

    res.end(String(payload))
    return res
  }

  res.download = function download(filePath, filename) {
    const fs = require("fs")
    const path = require("path")
    const stream = fs.createReadStream(filePath)

    res.statusCode = res.statusCode || 200
    res.setHeader("Content-Type", "application/pdf")
    res.setHeader("Content-Disposition", `attachment; filename="${filename || path.basename(filePath)}"`)

    stream.on("error", (error) => {
      if (!res.headersSent) {
        res.statusCode = 500
        res.end(error.message)
        return
      }
      res.destroy(error)
    })

    stream.pipe(res)
    return res
  }

  return res
}

function createRouter() {
  const routes = []
  const middlewares = []

  function addRoute(method, pathValue, handlers) {
    routes.push({
      method,
      path: normalizePath(pathValue),
      handlers
    })
  }

  async function runHandlers(stack, req, res) {
    let index = -1

    const dispatch = async (error) => {
      index += 1

      if (error) {
        throw error
      }

      const current = stack[index]

      if (!current) {
        return
      }

      return new Promise((resolve, reject) => {
        let settled = false

        const next = (nextError) => {
          if (settled) {
            return
          }
          settled = true
          if (nextError) {
            reject(nextError)
            return
          }
          resolve(dispatch())
        }

        try {
          const result = current(req, res, next)
          if (result && typeof result.then === "function") {
            result.then(() => {
              if (!settled) {
                settled = true
                resolve(dispatch())
              }
            }).catch(reject)
          } else if (current.length < 3 && !settled) {
            settled = true
            resolve(dispatch())
          }
        } catch (error) {
          reject(error)
        }
      })
    }

    return dispatch()
  }

  const router = function routerHandler(_req, _res, next) {
    if (typeof next === "function") {
      next()
    }
  }

  router.routes = routes
  router.middlewares = middlewares
  router.use = function use(pathOrHandler, ...handlers) {
    if (typeof pathOrHandler === "string") {
      const mountPath = normalizePath(pathOrHandler)
      if (handlers.length === 1 && handlers[0] && handlers[0].routes) {
        handlers[0].routes.forEach((route) => {
          routes.push({
            method: route.method,
            path: joinPaths(mountPath, route.path),
            handlers: route.handlers
          })
        })
        return router
      }

      handlers.forEach((handler) => {
        middlewares.push({ path: mountPath, handler })
      })
      return router
    }

    const handler = pathOrHandler
    if (handler && handler.routes) {
      handler.routes.forEach((route) => {
        routes.push({
          method: route.method,
          path: route.path,
          handlers: route.handlers
        })
      })
      return router
    }

    if (typeof handler === "function") {
      middlewares.push({ path: "/", handler })
    }

    return router
  }

  ;["get", "post", "put", "patch", "delete", "options"].forEach((method) => {
    router[method] = (pathValue, ...handlers) => {
      addRoute(method.toUpperCase(), pathValue, handlers)
      return router
    }
  })

  router._handle = async function handle(req, res, rootPath = "/") {
    const requestPath = normalizePath(parseUrl(req.url).pathname)
    const stack = []

    middlewares.forEach(({ path, handler }) => {
      if (requestPath === path || requestPath.startsWith(`${path}/`) || path === "/") {
        stack.push(handler)
      }
    })

    const matchedRoute = routes.find((route) => route.method === req.method && matchPath(route.path, requestPath))

    if (matchedRoute) {
      const params = matchPath(matchedRoute.path, requestPath) || {}
      req.params = params
      stack.push(...matchedRoute.handlers)
    }

    if (!matchedRoute && req.method !== "OPTIONS") {
      return false
    }

    await runHandlers(stack, req, res)
    return true
  }

  return router
}

function createApp() {
  const app = createRouter()
  const serverMiddlewares = []

  app.use = function use(pathOrHandler, ...handlers) {
    if (typeof pathOrHandler === "string") {
      const mountPath = normalizePath(pathOrHandler)
      if (handlers.length === 1 && handlers[0] && handlers[0].routes) {
        handlers[0].routes.forEach((route) => {
          app.routes.push({
            method: route.method,
            path: joinPaths(mountPath, route.path),
            handlers: route.handlers
          })
        })
        return app
      }

      handlers.forEach((handler) => {
        serverMiddlewares.push({ path: mountPath, handler })
      })
      return app
    }

    const handler = pathOrHandler
    if (handler && handler.routes) {
      handler.routes.forEach((route) => {
        app.routes.push({
          method: route.method,
          path: route.path,
          handlers: route.handlers
        })
      })
      return app
    }

    if (typeof handler === "function") {
      serverMiddlewares.push({ path: "/", handler })
    }

    return app
  }

  app.listen = function listen(port, callback) {
    const server = http.createServer(async (req, res) => {
      enhanceResponse(res)
      req.query = Object.fromEntries(new URL(req.url, `http://${req.headers.host || "localhost"}`).searchParams.entries())
      req.body = {}
      req.params = {}

      const chunks = []
      req.on("data", (chunk) => chunks.push(chunk))
      req.on("end", async () => {
        req.rawBody = Buffer.concat(chunks)
        try {
          const requestPath = normalizePath(parseUrl(req.url).pathname)
          const stack = []

          for (const { path, handler } of serverMiddlewares) {
            if (requestPath === path || requestPath.startsWith(`${path}/`) || path === "/") {
              stack.push(handler)
            }
          }

          const matchedRoute = app.routes.find((route) => route.method === req.method && matchPath(route.path, requestPath))

          if (matchedRoute) {
            req.params = matchPath(matchedRoute.path, requestPath) || {}
            stack.push(...matchedRoute.handlers)
          }

          if (!matchedRoute && req.method !== "OPTIONS") {
            res.statusCode = 404
            res.json({ error: "Not Found" })
            return
          }

          let index = 0
          const next = (error) => {
            if (error) {
              res.statusCode = error.statusCode || 500
              res.json({ error: error.message || "Internal Server Error" })
              return
            }

            const handler = stack[index++]
            if (!handler) {
              if (!res.writableEnded) {
                res.statusCode = res.statusCode || 204
                res.end()
              }
              return
            }

            try {
              const result = handler(req, res, next)
              if (result && typeof result.then === "function") {
                result.catch(next)
              }
            } catch (handlerError) {
              next(handlerError)
            }
          }

          next()
        } catch (error) {
          res.statusCode = 500
          res.json({ error: error.message || "Internal Server Error" })
        }
      })
    })

    return server.listen(port, callback)
  }

  return app
}

function express() {
  return createApp()
}

express.Router = createRouter

express.json = function json() {
  return (req, _res, next) => {
    const contentType = String(req.headers["content-type"] || "")
    if (!contentType.includes("application/json") || req.rawBody === undefined) {
      return next()
    }

    if (req.rawBody.length === 0) {
      req.body = {}
      return next()
    }

    try {
      req.body = JSON.parse(req.rawBody.toString("utf8"))
    } catch (_error) {
      req.body = {}
    }

    return next()
  }
}

module.exports = express
